package com.taller.portal.service;

import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.*; import java.io.*; import java.net.*; import java.net.http.*; import java.nio.file.*; import java.sql.*; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
/** Descarga opcionalmente e importa el catálogo NHTSA vPIC para uso local sin red en tiempo de ejecución. */
@Service public class VpicImportService {
 private static final String BASE="https://vpic.nhtsa.dot.gov/api/vehicles/"; private final JdbcTemplate jdbc; private final ObjectMapper json=new ObjectMapper(); private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(30)).build();
 /** @param jdbc acceso transaccional al catálogo local. */ public VpicImportService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 /** Conteos reproducibles de importación. */ public record Resultado(long marcasNuevas,long marcasExistentes,long modelosNuevos,long modelosExistentes,long omitidos,long totalMarcas,long totalModelos){}
 /** Importa un JSON vPIC agregado previamente descargado. La forma canónica es MAYÚSCULAS con espacios internos colapsados. @param archivo JSON local. @return conteos e inventario posterior. @throws IOException si falta o es inválido. */
 @Transactional public Resultado importar(Path archivo)throws IOException{if(archivo==null||!Files.isRegularFile(archivo))throw new FileNotFoundException("No existe el catálogo vPIC: "+archivo);JsonNode raiz=json.readTree(Files.newBufferedReader(archivo));JsonNode marcas=raiz.path("makes");if(!marcas.isArray())throw new IOException("El JSON vPIC requiere el arreglo makes");long mn=0,me=0,modn=0,mode=0,omit=0;for(JsonNode marca:marcas){Long makeId=numero(marca,"Make_ID");String nombre=texto(marca,"Make_Name");if(makeId==null||nombre==null){omit++;continue;}int altaMarca=jdbc.update("insert into vpic_marca (vpic_make_id,nombre) select ?,? where not exists (select 1 from vpic_marca where vpic_make_id=? or nombre=?)",makeId,nombre,makeId,nombre);if(altaMarca>0)mn++;else me++;Long marcaId=idMarca(makeId,nombre);JsonNode modelos=marca.path("models");if(!modelos.isArray()){omit++;continue;}for(JsonNode modelo:modelos){Long modelId=numero(modelo,"Model_ID");String nombreModelo=texto(modelo,"Model_Name");if(modelId==null||nombreModelo==null){omit++;continue;}int filas=jdbc.update("insert into vpic_modelo (marca_id,vpic_model_id,nombre) select ?,?,? where not exists (select 1 from vpic_modelo where marca_id=? and (vpic_model_id=? or nombre=?))",marcaId,modelId,nombreModelo,marcaId,modelId,nombreModelo);if(filas>0)modn++;else mode++;}}
  Long tm=jdbc.queryForObject("select count(*) from vpic_marca",Long.class), tmo=jdbc.queryForObject("select count(*) from vpic_modelo",Long.class);return new Resultado(mn,me,modn,mode,omit,tm==null?0:tm,tmo==null?0:tmo);}
 /** Descarga vPIC con progreso reanudable y reintentos; no se invoca salvo desde el script sin --archivo. @param destino JSON final. @throws IOException si la red falla tras tres intentos. @throws InterruptedException si se interrumpe la espera. */
 public void descargar(Path destino)throws IOException,InterruptedException{Files.createDirectories(destino.toAbsolutePath().getParent());Path parcial=destino.resolveSibling(destino.getFileName()+".progreso");ObjectNode raiz=Files.isRegularFile(parcial)?(ObjectNode)json.readTree(Files.newBufferedReader(parcial)):json.createObjectNode();ArrayNode makes=raiz.withArray("makes");Set<Long> ids=new HashSet<>();for(JsonNode n:makes)if(n.has("Make_ID"))ids.add(n.path("Make_ID").asLong());for(String tipo:List.of("car","mpv","truck")){for(JsonNode marca:pedir("GetMakesForVehicleType/"+tipo+"?format=json").path("Results")){Long id=numero(marca,"Make_ID");String nombre=texto(marca,"Make_Name");if(id==null||nombre==null||!ids.add(id))continue;ObjectNode item=makes.addObject();item.put("Make_ID",id);item.put("Make_Name",nombre);ArrayNode modelos=item.putArray("models");for(JsonNode modelo:pedir("GetModelsForMake/"+URLEncoder.encode(nombre,java.nio.charset.StandardCharsets.UTF_8)+"?format=json").path("Results"))modelos.add(modelo);guardar(parcial,raiz);}}raiz.put("downloadedAt",Instant.now().toString());raiz.put("source","NHTSA vPIC");guardar(destino,raiz);Files.deleteIfExists(parcial);}
 /** Solicita JSON con tres intentos, 30 s de timeout y pausa mínima entre llamadas. @param ruta segmento vPIC. @return respuesta JSON. @throws IOException al agotar intentos. @throws InterruptedException si se interrumpe. */
 private JsonNode pedir(String ruta)throws IOException,InterruptedException{IOException ultimo=null;for(int intento=1;intento<=3;intento++){try{Thread.sleep(200L*Math.max(1,intento));HttpRequest peticion=HttpRequest.newBuilder(URI.create(BASE+ruta)).timeout(Duration.ofSeconds(30)).GET().build();HttpResponse<String> respuesta=http.send(peticion,HttpResponse.BodyHandlers.ofString());if(respuesta.statusCode()/100!=2)throw new IOException("vPIC respondió HTTP "+respuesta.statusCode());return json.readTree(respuesta.body());}catch(IOException e){ultimo=e;if(intento<3)Thread.sleep(500L*intento);}}throw ultimo==null?new IOException("No se pudo consultar vPIC"):ultimo;}
 /** Obtiene el id local de una marca ya insertada o existente. @param makeId id NHTSA @param nombre nombre canónico. @return id local. */ private Long idMarca(Long makeId,String nombre){return jdbc.queryForObject("select id from vpic_marca where vpic_make_id=? or nombre=? order by id limit 1",Long.class,makeId,nombre);}
 /** Normaliza texto a MAYÚSCULAS, espacios únicos y sin extremos. @param nodo objeto JSON. @param campo llave requerida. @return texto canónico o null. */ private String texto(JsonNode nodo,String campo){if(!nodo.hasNonNull(campo))return null;String valor=nodo.path(campo).asText().replaceAll("\\s+"," ").trim().toUpperCase(Locale.ROOT);return valor.isBlank()?null:valor;}
 /** Obtiene un entero positivo de vPIC. @param nodo objeto JSON. @param campo llave requerida. @return id o null. */ private Long numero(JsonNode nodo,String campo){if(!nodo.hasNonNull(campo)||!nodo.path(campo).canConvertToLong())return null;long valor=nodo.path(campo).asLong();return valor>0?valor:null;}
 /** Escribe progreso de forma atómica. @param archivo destino. @param raiz JSON. @throws IOException si no puede persistirse. */ private void guardar(Path archivo,ObjectNode raiz)throws IOException{Path temporal=archivo.resolveSibling(archivo.getFileName()+".tmp");json.writerWithDefaultPrettyPrinter().writeValue(temporal.toFile(),raiz);Files.move(temporal,archivo,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 /** Imprime la cobertura de marcas solicitadas tras una importación. @return texto listo para consola. */ public String cobertura(){StringBuilder salida=new StringBuilder("Cobertura vPIC:\n");for(String marca:List.of("NISSAN","CHEVROLET","VOLKSWAGEN","TOYOTA","FORD","KIA","MAZDA","HONDA")){Long total=jdbc.queryForObject("select count(*) from vpic_modelo mo join vpic_marca ma on ma.id=mo.marca_id where ma.nombre=?",Long.class,marca);salida.append(marca).append(": ").append(total==null?0:total).append(" modelos").append((total==null||total<3)?" (revisar cobertura)":"").append('\n');}return salida.toString();}
}
